#!/usr/bin/env python3
"""Coder Agent — generates JS/TS/Python code."""
import sys, os, asyncio, datetime
sys.path.insert(0, os.path.dirname(os.path.dirname(os.path.abspath(__file__))))
from base_agent import Agent

agent = Agent("coder-agent", ["code", "javascript", "typescript", "python", "script"])

@agent.on("code", "javascript", "typescript", "python", "script")
async def code(tid, payload):
    msg  = payload.get("message", payload.get("prompt", "hello world script"))
    lang = payload.get("lang", "javascript")

    snippets = {
        "javascript": f'''// Generated by IAD Coder Agent — {datetime.date.today()}
// Task: {msg}

class App {{
  constructor(name) {{
    this.name = name;
    this.startedAt = new Date();
  }}

  greet() {{
    return `Hello from ${{this.name}}! Started at ${{this.startedAt.toISOString()}}`;
  }}

  async run() {{
    console.log(this.greet());
    console.log('Task: {msg}');
    // TODO: implement actual logic here
    return {{ status: 'ok', agent: 'coder-agent', task: '{msg}' }};
  }}
}}

const app = new App('IAD-App');
app.run().then(console.log).catch(console.error);
''',
        "python": f'''#!/usr/bin/env python3
# Generated by IAD Coder Agent — {datetime.date.today()}
# Task: {msg}

import asyncio
from datetime import datetime

class App:
    def __init__(self, name: str):
        self.name       = name
        self.started_at = datetime.now()

    def greet(self) -> str:
        return f"Hello from {{self.name}}! Started {{self.started_at:%H:%M:%S}}"

    async def run(self) -> dict:
        print(self.greet())
        print(f"Task: {msg}")
        # TODO: implement actual logic here
        return {{"status": "ok", "agent": "coder-agent", "task": "{msg}"}}

async def main():
    app = App("IAD-App")
    result = await app.run()
    print(result)

if __name__ == "__main__":
    asyncio.run(main())
''',
        "typescript": f'''// Generated by IAD Coder Agent — {datetime.date.today()}
// Task: {msg}

interface AppResult {{
  status: string;
  agent:  string;
  task:   string;
}}

class App {{
  constructor(private name: string) {{}}

  greet(): string {{
    return `Hello from ${{this.name}}! Task: {msg}`;
  }}

  async run(): Promise<AppResult> {{
    console.log(this.greet());
    return {{ status: "ok", agent: "coder-agent", task: "{msg}" }};
  }}
}}

const app = new App("IAD-App");
app.run().then(console.log);
'''
    }

    code_out = snippets.get(lang, snippets["javascript"])
    ext_map  = {"javascript": "js", "typescript": "ts", "python": "py"}
    ext      = ext_map.get(lang, "js")
    out      = payload.get("output", f"/tmp/code-{tid[:8]}.{ext}")
    with open(out, "w") as f: f.write(code_out)
    print(f"[coder] ✅ wrote {len(code_out)}b → {out}", flush=True)
    return {"file": out, "bytes": len(code_out), "lang": lang,
            "lines": len(code_out.splitlines()), "agent": "coder-agent"}

if __name__ == "__main__":
    asyncio.run(agent.run())
